#include<iostream>
#include <algorithm>
#include<vector>

using namespace std;
//Driver Code Ends


int kthSmallest(vector<int>& arr, int k)
{
    // Sort the given vector
    sort(arr.begin(), arr.end());

    // Return k'th element in the sorted vector
    return arr[k - 1];
}


