using System;

class MaxHeap
{
    private int[] heap;
    private int size;

    public MaxHeap(int capacity)
    {
        heap = new int[capacity];
        size = 0;
    }

    public int Count => size;

    public void Push(int val)
    {
        heap[size] = val;
        int i = size;
        size++;
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (heap[parent] >= heap[i])
                break;
            int temp = heap[parent];
            heap[parent] = heap[i];
            heap[i] = temp;
            i = parent;
        }
    }

    public int Pop()
    {
        if (size == 0)
        {
            Console.WriteLine("Heap is empty");
            return -1; 
        }

        int top = heap[0];
        heap[0] = heap[size - 1];
        size--;

        int i = 0;
        while (true)
        {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int largest = i;

            if (left < size && heap[left] > heap[largest])
                largest = left;
            if (right < size && heap[right] > heap[largest])
                largest = right;
            if (largest == i)
                break;

            int temp = heap[i];
            heap[i] = heap[largest];
            heap[largest] = temp;

            i = largest;
        }
        return top;
    }

    public int Top()
    {
        if (size == 0)
        {
            Console.WriteLine("Heap is empty");
            return -1; 
        }
        return heap[0];
    }
}

