Output5[Alternative Approach 1] Using QuickSelect The main idea is to use QuickSelect to find the k-th largest element by picking a pivot and partitioning the array so that all elements greater than the pivot are on the left and smaller ones on the right. If the pivot ends up at index k–1, it is the k-th largest element. Otherwise, we recursively search only in the left or right part that contains the k-th largest element.
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
using namespace std;
//Driver Code Ends


int partition(vector<int>& arr, int left, int right) {

     // Choose the last element as pivot
    int pivot = arr[right]; 
    int i = left; 

    // Traverse the array and move elements <= pivot to the left
    for(int j = left; j < right; j++) {
        if(arr[j] <= pivot) {

             // Swap current element with element at i
            swap(arr[i], arr[j]);
            i++;                  
        }
    }

    // Place the pivot in its correct position
    swap(arr[i], arr[right]);
    return i;
}

// QuickSelect function: recursively finds k-th smallest
int quickSelect(vector<int>& arr, int left, int right, int k) {

    if(left <= right) {

        // Partition around pivot
        int pivotIndex = partition(arr, left, right); 

         // Found k-th smallest
        if(pivotIndex == k) return arr[pivotIndex];  

        else if(pivotIndex > k) 
        return quickSelect(arr, left, pivotIndex - 1, k);

        else return quickSelect(arr, pivotIndex + 1, right, k);
    }
    return -1;
}

int kthSmallest(vector<int>& arr, int k) {
    return quickSelect(arr, 0, arr.size()-1, k-1);
}


